package com.fitpulse.service;
import com.fitpulse.exception.FitPulseException; import com.fitpulse.model.dto.WorkoutEventForm; import com.fitpulse.model.entity.*; import com.fitpulse.model.enums.WorkoutStatus; import com.fitpulse.repository.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.time.LocalDateTime; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class WellnessServiceTest {
 @Mock WorkoutEventRepository events;@Mock GymRepository gyms;@Mock ProgramTemplateRepository templates;@Mock UserProgramRepository programs;@Mock UserProgramItemRepository items;@Mock MealPlanTemplateRepository mealTemplates;@Mock UserMealPlanRepository mealPlans;@Mock UserService users;WellnessService service;User user;
 @BeforeEach void setup(){service=new WellnessService(events,gyms,templates,programs,items,mealTemplates,mealPlans,users);user=new User();when(users.getCurrentUser()).thenReturn(user);}
 @Test void createsPersonalCalendarEvent(){WorkoutEventForm f=new WorkoutEventForm();f.setTitle("Run");f.setStartsAt(LocalDateTime.now());f.setDurationMinutes(45);service.saveEvent(null,f);ArgumentCaptor<WorkoutEvent> c=ArgumentCaptor.forClass(WorkoutEvent.class);verify(events).save(c.capture());assertSame(user,c.getValue().getUser());assertEquals(45,c.getValue().getDurationMinutes());}
 @Test void cannotEditOtherUsersEvent(){when(events.findByIdAndUser(9L,user)).thenReturn(Optional.empty());assertThrows(FitPulseException.class,()->service.eventStatus(9L, WorkoutStatus.COMPLETED));}
 @Test void userSelectsActiveProgramAndGetsIndependentCopy(){ProgramTemplate t=new ProgramTemplate();t.setName("Template");t.setTrainingDays(3);when(templates.findById(1L)).thenReturn(Optional.of(t));when(programs.save(any())).thenAnswer(i->i.getArgument(0));service.copyProgram(1L);verify(programs).save(any());verify(items,times(9)).save(any());assertTrue(t.getItems().isEmpty());}
 @Test void mealCopyIncludesExampleFoods(){MealPlanTemplate t=new MealPlanTemplate();t.setName("Balanced");t.setMeals("Meals");t.setExampleFoods("Foods");when(mealTemplates.findById(1L)).thenReturn(Optional.of(t));service.copyMeal(1L);ArgumentCaptor<UserMealPlan> c=ArgumentCaptor.forClass(UserMealPlan.class);verify(mealPlans).save(c.capture());assertSame(user,c.getValue().getUser());assertEquals("Foods",c.getValue().getExampleFoods());}
 @Test void missingOwnedProgramIsRejected(){when(programs.findByIdAndUser(1L,user)).thenReturn(Optional.empty());assertThrows(FitPulseException.class,()->service.ownedProgram(1L));}
}
